/**
 * 登录用户提交一条提案（实体域 §4.9）。**当前只开放 `kind=new_benchmark`** ——
 * `report` 已作废（治理域 §2.2：论坛外置后不建举报队列），`merge_*` / `retag_demo` /
 * `task_match` 属管理员或 agent 场景，其余 kind 随各自的规格票逐个放开。
 * 白名单之外的 kind 一律 `422`，不假装受理。
 *
 * 去重按 `(kind, dedupe_key)` **只查 `pending`**：同一份内容被驳回或撤回之后可以重新提交。
 * 命中已有 pending 时返回 `202` + 原 id + `created=false`，**不新建行**（幂等，不是错误）。
 *
 * 通过之后的执行器按 kind 接入（`new_benchmark` 见 #525）；未接入的 kind 在裁决时明确 `422`。
 * @summary 提交一条提案
 */
export const submitProposal = async (proposalSubmission: ProposalSubmission, options?: RequestInit): Promise<submitProposalResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
const res = await fetch(getSubmitProposalUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(proposalSubmission)
  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: submitProposalResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as submitProposalResponse
}


